(function(){
const blocks=window.jali.types.map(t=>t[0]);
const block={type:'string',enum:blocks,description:'flower is the symmetric open petal form; funnel is the recessed, more opaque privacy block; solid is fully opaque.'};
const rotation={type:'integer',enum:[0,90,180,270],description:'Clockwise from the front.'};
const bounds={start_row:{type:'integer',minimum:1,description:'1-based from the TOP; omitted means first row.'},end_row:{type:'integer',minimum:1,description:'Inclusive; omitted means last row.'},start_column:{type:'integer',minimum:1},end_column:{type:'integer',minimum:1}};
const schema=(properties,required=[])=>({type:'object',properties,required,additionalProperties:false});
const tools=[
{name:'jali_apply_rhythm',title:'Apply an inspired wall rhythm',description:'Fill the wall with an available composition, in one undoable edit. Read jali_get_design.available_rhythms first. Includes framed fields, privacy fade, 2:1 simple/ornate mixes, stripes, rotating pinwheels, rosettes, paired arches, chevrons and medallions. Repeats start at the top left and can be partial at edges.',inputSchema:schema({rhythm_id:{type:'string',enum:window.jali.rhythms.map(r=>r.id)}},['rhythm_id']),action:'rhythm'},
{name:'jali_apply_combo',title:'Stamp or repeat a multi-block combination',description:'Place an assembly of separate blocks at a 1-based top-left anchor, or repeat it from that anchor to the bottom/right wall edges. Read available_combos first; combo_id can also refer to a user-saved patch. rotation turns the entire grid AND each constituent block. A single stamp must fit fully; repeated edge motifs may be partial. Empty cells in a saved combo clear those wall cells. One undoable edit.',inputSchema:schema({combo_id:{type:'string'},row:{type:'integer',minimum:1,default:1},column:{type:'integer',minimum:1,default:1},rotation,repeat:{type:'boolean',default:false}},['combo_id']),action:'combo'},
{name:'jali_capture_combo',title:'Save a wall patch as a reusable combo',description:'Capture a rectangle, up to 6 by 6 cells, from the current wall. Coordinates are 1-based from the top left. Returns a new saved_combo_id usable with jali_apply_combo. Saves with the design and exported JSON; maximum 30 custom combos.',inputSchema:schema({name:{type:'string',minLength:1,maxLength:50},row:{type:'integer',minimum:1},column:{type:'integer',minimum:1},rows:{type:'integer',minimum:1,maximum:6},columns:{type:'integer',minimum:1,maximum:6}},['name','row','column','rows','columns']),action:'capture'},
{name:'jali_get_design',title:'Inspect jali wall',description:'Read the current visible wall design, real dimensions, block quantities, row-by-row composition, selection, lighting and view. Read this before editing. Coordinates are 1-based with row 1 at the TOP. Set include_cells for individual block types and rotations.',inputSchema:schema({include_cells:{type:'boolean'}}),action:'read',readOnly:true},
{name:'jali_configure_wall',title:'Set wall dimensions and material',description:'Set the real opening dimensions, square block size, depth, joints, base height or clay finish. Existing blocks are preserved where possible; new grid cells use the current brush. Dimensions refer to the opening above the sill. Layout saves and can be undone.',inputSchema:schema({width:{type:'number'},height:{type:'number'},units:{type:'string',enum:['ft','m','mm'],default:'ft'},block_size_mm:{type:'number',minimum:100,maximum:450},depth_mm:{type:'number',minimum:50,maximum:200},joint_mm:{type:'number',minimum:0,maximum:20},sill_mm:{type:'number',minimum:0,maximum:900},finish:{type:'string',enum:['earth','rose','sienna','sand']}}),action:'configure'},
{name:'jali_compose_wall',title:'Compose a wall pattern',description:'Replace the whole wall with a structured pattern in one undoable edit. For privacy_below, PRIMARY fills the upper rows and SECONDARY fills the bottom band. Defaults are flower above and funnel below; choose solid for completely opaque. bottom_rows or bottom_fraction sets the band (default 40%). For border, secondary is the outer border and primary is the field. Rotations are fixed per block type; use jali_rotate_region for alternating rotations.',inputSchema:schema({pattern:{type:'string',enum:['privacy_below','uniform','checkerboard','alternating_rows','alternating_columns','border']},primary_block:block,secondary_block:block,primary_rotation:rotation,secondary_rotation:rotation,bottom_rows:{type:'integer',minimum:0},bottom_fraction:{type:'number',minimum:0,maximum:1,description:'Fraction of grid rows at the bottom. Use this OR bottom_rows.'}},['pattern']),action:'compose'},
{name:'jali_fill_region',title:'Fill or clear a wall region',description:'Fill an inclusive rectangle of cells with one block and rotation, or use block:null to clear it. Rows start at 1 at the top. Omitted bounds span the whole grid. Read grid dimensions before choosing bounds. This is one undoable edit.',inputSchema:schema({...bounds,block:{anyOf:[block,{type:'null'}]},rotation},['block']),action:'fill'},
{name:'jali_edit_blocks',title:'Edit individual jali blocks',description:'Batch 1–500 explicit block placements, replacements or removals as one undoable edit. Coordinates are 1-based from the top left. block:null removes a block. All input is checked before applying any edit.',inputSchema:schema({edits:{type:'array',minItems:1,maxItems:500,items:schema({row:{type:'integer',minimum:1},column:{type:'integer',minimum:1},block:{anyOf:[block,{type:'null'}]},rotation},['row','column','block'])}},['edits']),action:'blocks'},
{name:'jali_rotate_region',title:'Rotate existing blocks',description:'Rotate existing blocks in an inclusive rectangular region without replacing their types. Positive degrees are clockwise. Alternating checkerboard selection permits woven and interlocking rhythms. Empty cells stay empty. Omitted bounds select the whole wall.',inputSchema:schema({...bounds,degrees:{type:'integer',enum:[-270,-180,-90,90,180,270]},alternating:{type:'string',enum:['all','checkerboard_even','checkerboard_odd']}},['degrees']),action:'rotate'},
{name:'jali_set_sunlight',title:'Adjust sunlight and shadows',description:'Set directional sunlight for the live 3D scene. elevation is degrees above the ground; azimuth is degrees to either side of the outward wall normal; strength 0 gives overcast light. Presets can be overridden with explicit values. This is an exploratory geometry-based light study, not date/location-specific daylight analysis. Changes open the 3D view.',inputSchema:schema({preset:{type:'string',enum:['raking','high_sun','golden_hour','overcast']},elevation:{type:'number',minimum:8,maximum:80},azimuth:{type:'number',minimum:-80,maximum:80},strength:{type:'number',minimum:0,maximum:5}}),action:'light'},
{name:'jali_set_view',title:'Inspect the wall in space',description:'Switch between the 3D space and editable elevation; choose front, oblique, floor-shadow or selected-block closeup camera. Toggle real dimension annotations and the 1.70 metre scale figure.',inputSchema:schema({view:{type:'string',enum:['3d','elevation']},camera:{type:'string',enum:['front','oblique','shadows','closeup']},show_dimensions:{type:'boolean'},show_person:{type:'boolean'}}),action:'view'},
{name:'jali_undo_design',title:'Undo or redo design edits',description:'Undo or redo up to 20 wall design edits. This uses the same history as the editor. Sunlight and camera changes are independent of design history.',inputSchema:schema({steps:{type:'integer',minimum:1,maximum:20,default:1},direction:{type:'string',enum:['undo','redo'],default:'undo'}}),action:'undo'}
];
let lifecycle=null,registered=0,errors=[];
function status(){const ready=registered===tools.length;document.querySelector('#agentDot').textContent=ready?'●':'◌';document.querySelector('#agentHelp').title=ready?`${registered} WebMCP tools available in this tab`:'WebMCP requires a supported browser connection';document.querySelector('#agentHelp').classList.toggle('agent-ready',ready)}
async function register(){if(lifecycle)return;const registry=document.modelContext;if(typeof registry?.registerTool!=='function'){status();return}lifecycle=new AbortController();registered=0;errors=[];for(const t of tools){try{await registry.registerTool({name:t.name,title:t.title,description:t.description,inputSchema:t.inputSchema,annotations:{readOnlyHint:!!t.readOnly},async execute(input){try{const result=window.jali.actions[t.action](input??{});return {content:[{type:'text',text:JSON.stringify(result)}]}}catch(e){return {isError:true,content:[{type:'text',text:e.message||'Design action failed'}]}}}},{signal:lifecycle.signal});registered++}catch(e){errors.push(t.name);console.warn('WebMCP tool registration failed:',t.name,e)}status()}}
window.addEventListener('pagehide',()=>{lifecycle?.abort();lifecycle=null});window.addEventListener('pageshow',e=>{if(e.persisted)register()});
document.querySelector('#agentHelp').onclick=()=>{const modal=document.querySelector('#modal');document.querySelector('#modalTitle').textContent='Design by conversation';document.querySelector('#modalContent').innerHTML=`<div class="agent-help"><div class="agent-status ${registered===tools.length?'ready':''}">${registered===tools.length?`${registered} WebMCP tools are ready in this tab`:'WebMCP is not connected in this browser'}</div><p>Keep this page open in a browser that supports ChatGPT’s WebMCP connection. Ask your assistant to inspect the wall, then describe the change you want.</p><div class="prompt-examples"><blockquote>Make the bottom 40% private with recessed blocks and use symmetric flowers above.</blockquote><blockquote>Make the opening 3 metres wide and 2.1 metres high, with 200 mm blocks and 8 mm joints.</blockquote><blockquote>Rotate alternate privacy blocks by 180°, then show low sunlight casting onto the floor.</blockquote></div><p class="small muted">The tools edit this live wall, preserve undo history, and save in this browser. There is no separate AI chat service inside the app. In an unsupported browser, use the visual controls or open the page in your connected browser.</p><details><summary>${tools.length} available tools</summary><ul>${tools.map(t=>`<li><code>${t.name}</code> — ${t.title}</li>`).join('')}</ul></details>${errors.length?'<p class="small muted">Some tools could not register. Reopen the tab to retry.</p>':''}</div>`;modal.showModal()};
// Exposed definitions make the same surface testable without a live agent session.
window.jali.webmcp={definitions:tools.map(({action,readOnly,...t})=>t),get registered(){return registered}};
register();
})();
